{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Google Cloud Storage bucket does not enforce uniform bucket-level access",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks the 'uniform_bucket_level_access' setting, which defaults to false. This allows legacy ACLs to coexist with IAM policies, potentially leading to inconsistent or overly permissive access controls for compliance data."
    },
    {
      "check_id": "CKV_GCP_11",
      "title": "Google Cloud Storage bucket does not have public access prevention enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "HIGH",
      "explanation": "The bucket does not set 'public_access_prevention' to 'enforced'. Without this, accidental misconfigurations in IAM or ACLs could expose sensitive compliance storage data to the public internet."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name     = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location = var.region\n  versioning {\n    enabled = true\n  }\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n  uniform_bucket_level_access = true\n  public_access_prevention    = \"enforced\"\n}",
  "fix_summary": "Added 'uniform_bucket_level_access = true' to enforce consistent IAM-based access control and disabled legacy ACLs. Added 'public_access_prevention = \"enforced\"' to prevent any future configuration from making the bucket publicly accessible."
}
